"use strict";
/* Branche 6 : scattering covariance et séparation de composantes. Chaque référence a été vérifiée en ligne. */
window.B6={
refs:{
portilla2000:{a:"Portilla, J. et Simoncelli, E. P.",short:"Portilla et Simoncelli (2000)",y:2000,t:"A parametric texture model based on joint statistics of complex wavelet coefficients",j:"International Journal of Computer Vision",v:"40(1)",p:"49–71",doi:"10.1023/A:1026553619983",th:"scattering",
 q:"Quelles statistiques suffisent pour qu'une texture synthétique ressemble à l'originale ?",
 ap:"Décrit une texture par des statistiques calculées sur des paires de coefficients d'ondelettes complexes voisins en position, en orientation et en échelle, puis synthétise de nouvelles images qui respectent ces statistiques.",
 g:"C'est l'ancêtre direct des idées de cette branche : coupler les échelles, puis générer pour vérifier.",pre:[]},
mallat2012:{a:"Mallat, S.",short:"Mallat (2012)",y:2012,t:"Group invariant scattering",j:"Communications on Pure and Applied Mathematics",v:"65(10)",p:"1331–1398",doi:"10.1002/cpa.21413",th:"scattering",
 q:"Peut-on construire une représentation invariante par translation et stable quand l'image se déforme ?",
 ap:"Définit la transformée de scattering : une cascade d'opérateurs dont chacun calcule le module d'une transformée en ondelettes. Le résultat est invariant par translation et continu au sens de Lipschitz face aux déformations. Pour un processus stationnaire, les coefficients dépendent de moments d'ordre élevé et distinguent des processus de même spectre de puissance.",
 g:"Article de mathématiques, long et exigeant. À aborder après un texte d'introduction.",pre:["cheng2021guide"]},
bruna2013:{a:"Bruna, J. et Mallat, S.",short:"Bruna et Mallat (2013)",y:2013,t:"Invariant scattering convolution networks",j:"IEEE Transactions on Pattern Analysis and Machine Intelligence",v:"35(8)",p:"1872–1886",doi:"10.1109/TPAMI.2012.230",th:"scattering",
 q:"Que vaut le scattering comme réseau convolutif sans apprentissage ?",
 ap:"Présente le scattering comme un réseau qui enchaîne convolutions par ondelettes, module et moyenne. Il distingue des textures qui ont le même spectre de Fourier et atteint l'état de l'art de l'époque en reconnaissance de chiffres manuscrits et de textures.",
 g:"Les filtres sont fixés à l'avance : rien n'est appris, ce qui rend les coefficients interprétables.",pre:["mallat2012"]},
bruna2019:{a:"Bruna, J. et Mallat, S.",short:"Bruna et Mallat (2019)",y:2019,t:"Multiscale sparse microcanonical models",j:"Mathematical Statistics and Learning",v:"1(3/4)",p:"257–315",doi:"10.4171/MSL/7",th:"scattering",
 q:"Comment tirer de nouvelles réalisations d'un processus dont on ne connaît qu'un exemple ?",
 ap:"Définit des modèles microcanoniques conditionnés par un vecteur d'énergie mesuré sur une seule réalisation. L'échantillonnage part d'un bruit d'entropie maximale et le transporte par descente de gradient jusqu'à respecter les contraintes. Appliqué aux ondelettes et au scattering pour synthétiser des textures.",
 g:"Le modèle obtenu par descente de gradient n'est pas exactement le modèle d'entropie maximale : l'article étudie cet écart.",pre:["bruna2013"]},
allys2019:{a:"Allys, E., Levrier, F., Zhang, S., Colling, C., Regaldo-Saint Blancard, B., Boulanger, F., Hennebelle, P. et Mallat, S.",short:"Allys et al. (2019)",y:2019,t:"The RWST, a comprehensive statistical description of the non-Gaussian structures in the ISM",j:"Astronomy & Astrophysics",v:"629",p:"A115",doi:"10.1051/0004-6361/201834975",th:"scattering",
 q:"Le scattering peut-il décrire les structures non gaussiennes du milieu interstellaire ?",
 ap:"Introduit le scattering en astrophysique et le réduit en ajustant la dépendance angulaire des coefficients. Le résultat, la RWST, tient en moins de 100 coefficients pour six échelles et huit angles sur des cartes de 256 par 256, et quantifie les couplages entre échelles.",
 g:"La réduction suppose une régularité angulaire des coefficients, vérifiée sur les champs étudiés.",pre:["bruna2013"]},
allys2020:{a:"Allys, E., Marchand, T., Cardoso, J.-F., Villaescusa-Navarro, F., Ho, S. et Mallat, S.",short:"Allys et al. (2020)",y:2020,t:"New interpretable statistics for large-scale structure analysis and generation",j:"Physical Review D",v:"102",p:"103506",doi:"10.1103/PhysRevD.102.103506",th:"scattering",
 q:"Peut-on avoir des statistiques à la fois informatives, génératives et interprétables ?",
 ap:"Introduit les statistiques WPH (wavelet phase harmonics) pour des champs 2D non gaussiens. Sur des simulations de structure à grande échelle, elles contraignent mieux quatre paramètres cosmologiques sur cinq que spectre et bispectre réunis, et permettent de générer de nouveaux champs par un modèle d'entropie maximale.",
 g:"Les WPH couplent les échelles en alignant les phases des coefficients, une autre route que le module utilisé par le scattering.",pre:["allys2019"]},
cheng2021guide:{a:"Cheng, S. et Ménard, B.",short:"Cheng et Ménard (2021)",y:2021,t:"How to quantify fields or textures? A guide to the scattering transform",j:"arXiv",v:"",p:"2112.01288",doi:"10.48550/arXiv.2112.01288",th:"scattering",
 q:"Comment expliquer le scattering à un physicien, sans le formalisme mathématique ?",
 ap:"Guide volontairement peu technique. Il situe le scattering entre le spectre de puissance et les réseaux convolutifs, interprète ses coefficients et le rôle de chaque opération, et montre des synthèses de textures pour plusieurs champs physiques.",
 g:"Prépublication. C'est le meilleur point d'entrée de toute la branche.",pre:[]},
morel2022:{a:"Morel, R., Rochette, G., Leonarduzzi, R., Bouchaud, J.-P. et Mallat, S.",short:"Morel et al. (2022)",y:2022,t:"Scale dependencies and self-similar models with wavelet scattering spectra",j:"arXiv",v:"",p:"2204.10177",doi:"10.48550/arXiv.2204.10177",th:"scattering",
 q:"Comment capturer les dépendances entre échelles d'une série temporelle ?",
 ap:"Introduit les spectres de scattering, appelés covariances de scattering dans la première version. Les dépendances entre échelles sont mesurées par la covariance des coefficients d'ondelettes et de leur module, qu'une seconde transformée en ondelettes rend presque diagonale. Sert à bâtir des modèles d'entropie maximale pour la finance et la turbulence.",
 g:"Écrit pour des séries temporelles, donc en une dimension. Le cas des images vient avec Cheng et al. (2024).",pre:["bruna2019"]},
cheng2024:{a:"Cheng, S., Morel, R., Allys, E., Ménard, B. et Mallat, S.",short:"Cheng et al. (2024)",y:2024,t:"Scattering spectra models for physics",j:"PNAS Nexus",v:"3(4)",p:"pgae103",doi:"10.1093/pnasnexus/pgae103",th:"scattering",
 q:"Existe-t-il un modèle statistique générique pour les champs physiques, estimable sur un seul exemple ?",
 ap:"Étend les spectres de scattering aux champs 2D. Ces statistiques sont des covariances de coefficients de scattering, c'est-à-dire d'ondelettes suivies d'un module. Elles donnent une description compacte, réduite encore en exploitant symétries et régularité, utilisable pour l'inférence, la génération et la séparation de composantes.",
 g:"Les modèles visent des champs stationnaires. C'est la référence pour les coefficients S1 à S4.",pre:["morel2022","allys2020"]},
mousset2024:{a:"Mousset, L., Allys, E., Price, M. A., Aumont, J., Delouis, J.-M., Montier, L. et McEwen, J. D.",short:"Mousset et al. (2024)",y:2024,t:"Generative models of astrophysical fields with scattering transforms on the sphere",j:"arXiv, accepté dans Astronomy & Astrophysics",v:"",p:"2407.07007",doi:"10.48550/arXiv.2407.07007",th:"scattering",
 q:"Les covariances de scattering fonctionnent-elles sur la sphère ?",
 ap:"Étend les covariances de scattering aux cartes sphériques et s'en sert pour construire des modèles génératifs de champs astrophysiques.",
 g:"Fiche rédigée à partir de l'introduction de l'article : à compléter après lecture.",pre:["cheng2024"]},
regaldo2021:{a:"Regaldo-Saint Blancard, B., Allys, E., Boulanger, F., Levrier, F. et Jeffrey, N.",short:"Regaldo-Saint Blancard et al. (2021)",y:2021,t:"A new approach for the statistical denoising of Planck interstellar dust polarization data",j:"Astronomy & Astrophysics",v:"649",p:"L18",doi:"10.1051/0004-6361/202140503",th:"separation",
 q:"Peut-on retrouver les statistiques d'un signal noyé dans le bruit, sans modèle du signal ?",
 ap:"Pose le problème d = s + n, avec autant de réalisations du bruit que nécessaire. La méthode optimise une carte dans l'espace des pixels pour que ses statistiques WPH, une fois le bruit ajouté, reproduisent celles des données. Validée sur une simulation avec 300 réalisations de bruit Planck, puis appliquée à la région Chamaeleon-Musca à 353 GHz.",
 g:"La carte débruitée reproduit le vrai spectre jusqu'à des échelles où le bruit est dix fois plus puissant que le signal. Il faut savoir simuler le bruit.",pre:["allys2020"]},
delouis2022:{a:"Delouis, J.-M., Allys, E., Gauvrit, E. et Boulanger, F.",short:"Delouis et al. (2022)",y:2022,t:"Non-Gaussian modelling and statistical denoising of Planck dust polarisation full-sky maps using scattering transforms",j:"Astronomy & Astrophysics",v:"668",p:"A122",doi:"10.1051/0004-6361/202244566",th:"separation",
 q:"Le débruitage statistique passe-t-il à l'échelle du ciel entier ?",
 ap:"Calcule les coefficients de scattering sur la pixellisation HEALPix et ajoute des statistiques croisées, entre demi-missions et entre température et polarisation. L'algorithme sépare la poussière polarisée du bruit sur les cartes Planck, et gère les variations des statistiques sur le ciel.",
 g:"Là où le signal est dix fois plus faible que le bruit, les structures retrouvées ont les bonnes statistiques mais ne coïncident plus spatialement avec les vraies.",pre:["regaldo2021"]},
auclair2024:{a:"Auclair, C., Allys, E., Boulanger, F., Béthermin, M., Gkogkou, A., Lagache, G., Marchal, A., Miville-Deschênes, M.-A., Regaldo-Saint Blancard, B. et Richard, P.",short:"Auclair et al. (2024)",y:2024,t:"Separation of dust emission from the cosmic infrared background in Herschel observations with wavelet phase harmonics",j:"Astronomy & Astrophysics",v:"681",p:"A1",doi:"10.1051/0004-6361/202346814",th:"separation",
 q:"Peut-on séparer deux composantes toutes deux non gaussiennes, à une seule fréquence ?",
 ap:"Sépare l'émission de la poussière galactique du fond infrarouge cosmologique dans des cartes Herschel à 250 µm, en s'appuyant sur leur structure spatiale différente. Les statistiques du fond sont apprises sur une autre région du ciel, presque dépourvue de poussière.",
 g:"La séparation exige un exemple de la composante à retirer, observé ailleurs.",pre:["regaldo2021","delouis2022"]},
siahkoohi2023:{a:"Siahkoohi, A., Morel, R., Balestriero, R., Allys, E., Sainton, G., Kawamura, T. et de Hoop, M. V.",short:"Siahkoohi et al. (2023)",y:2023,t:"Multi-scale clustering and source separation of InSight mission seismic data",j:"arXiv",v:"",p:"2305.16189",doi:"10.48550/arXiv.2305.16189",th:"separation",
 q:"Que faire quand on ne sait même pas quelles sources sont présentes ?",
 ap:"Regroupe d'abord les signaux par un autoencodeur variationnel factoriel entraîné dans l'espace des spectres de scattering, à plusieurs échelles de temps. Les échantillons de chaque groupe servent ensuite d'a priori pour une séparation de sources posée comme une optimisation dans ce même espace. Appliqué aux données sismiques de la mission InSight sur Mars.",
 g:"Approche non supervisée pour des séries temporelles. Les premières versions portaient un autre titre.",pre:["morel2022"]},
tsouros2026:{a:"Tsouros, A., Russier, E., Allys, E., Auclair, C., Boulanger, F. et Delabrouille, J.",short:"Tsouros et al. (2026)",y:2026,t:"Separation of polarized dust emission in Planck observations with scattering transforms",j:"arXiv",v:"",p:"2602.04528",doi:"10.48550/arXiv.2602.04528",th:"separation",
 q:"Comment combiner plusieurs contraintes statistiques pour séparer la poussière polarisée de sa contamination ?",
 ap:"Modèle d = s + c pour chaque paramètre de Stokes, où c réunit bruit et résidus du fond cosmologique. Les statistiques sont des covariances de scattering, avec le logarithme de S1 et S2. Sept pertes sont sommées : cohérence avec les données, cohérence du résidu avec la contamination, statistiques croisées entre Q et U et avec une carte d'intensité à 857 GHz. Optimisation L-BFGS dans l'espace des pixels.",
 g:"Pas d'incertitudes fournies, et un résultat sensible à la qualité du modèle de contamination. Prépublication.",pre:["cheng2024","delouis2022","auclair2024"]}
},
lessons:[
{id:"s1",t:"Décrire une texture sans la recopier",lvl:"Découverte",min:4,scene:["waves",41,{mw:.45,a:.5}],src:["cheng2021guide"],
 cards:[
  {h:"Deux images, une seule mer",p:[`Regarde ces deux vignettes. Aucun pixel n'est identique de l'une à l'autre. Pourtant tu dirais sans hésiter que c'est « la même mer ».`,`Ce que tu reconnais n'est pas l'image elle-même. C'est sa <b>texture</b> : la taille des motifs, leur direction, leur contraste.`],figs:[["waves",41,{mw:.45,a:.5,lw:.09},"Tirage 1"],["waves",77,{mw:.45,a:.5,lw:.09},"Tirage 2"]]},
  {h:"Processus et réalisation",p:[`Les statisticiens disent : il existe un <b>processus</b> aléatoire, la règle qui fabrique la mer, et chaque image en est une <b>réalisation</b>, un tirage.`,`Toute cette branche répond à une question : quels nombres calculer sur une image pour caractériser le processus, et pas le tirage ? On les appelle des <b>statistiques résumées</b>.`]},
  {h:"Ce qu'on attend d'un bon résumé",p:[`Il doit donner presque la même valeur pour deux tirages du même processus. Il doit donner des valeurs différentes pour deux processus différents. Et il doit tenir en peu de nombres, pour être estimé sur une seule image.`,`{{cheng2021guide}} posent le problème ainsi, et c'est le fil que nous suivrons : moyenne, spectre, ondelettes, scattering.`]}],
 ex:[
  {k:"qcm",q:"Deux vignettes de la même mer, prises à deux instants. Qu'ont-elles en commun ?",o:["Leurs propriétés statistiques","La valeur de chaque pixel","Rien du tout"],why:"Ce sont deux réalisations du même processus : les pixels changent, la texture reste.",src:"cheng2021guide"},
  {k:"match",q:"Associe chaque mot à sa définition.",pairs:[["Processus","La règle aléatoire qui fabrique les images"],["Réalisation","Une image particulière, un tirage"],["Statistique résumée","Un nombre calculé sur l'image pour caractériser la règle"]],why:"On observe des réalisations, on cherche à décrire le processus, et les statistiques résumées font le lien.",src:"cheng2021guide"},
  {k:"qcm",q:"Quelle qualité n'attend-on PAS d'une statistique résumée ?",o:["Changer fortement d'un tirage à l'autre du même processus","Distinguer deux processus différents","Tenir en peu de nombres"],why:"Une bonne statistique est stable entre tirages. Si elle varie beaucoup, elle décrit le tirage et pas le processus.",src:"cheng2021guide"}]},
{id:"s2",t:"Moyenne et variance : un début",lvl:"Découverte",min:4,scene:["grf",5,{beta:1.2}],src:["cheng2021guide"],
 cards:[
  {h:"Les deux premiers nombres",p:[`La <b>moyenne</b> dit si l'image est globalement claire ou sombre. La <b>variance</b> dit si le contraste est fort ou faible. Ce sont les statistiques les plus simples.`]},
  {h:"Pourquoi cela ne suffit pas",p:[`Ces deux champs ont exactement la même moyenne et la même variance. L'un est fait de grains fins, l'autre de grandes taches.`,`La moyenne et la variance ne regardent chaque pixel qu'isolément. Elles ignorent comment les pixels voisins se ressemblent, donc la <b>taille</b> des structures.`],figs:[["grf",5,{beta:.8},"Grains fins"],["grf",5,{beta:3},"Grandes taches"]]},
  {h:"L'idée suivante",p:[`Il faut une statistique qui trie l'information par échelle : combien de contraste dans les petits détails, combien dans les grands. C'est exactement ce que fait le spectre de puissance.`]}],
 ex:[
  {k:"qcm",q:"Deux images ont la même moyenne et la même variance. Sont-elles forcément de la même texture ?",o:["Non, la taille des structures peut différer","Oui, toujours","Oui, si elles ont la même taille en pixels"],why:"Moyenne et variance ne disent rien de l'organisation spatiale.",src:"cheng2021guide"},
  {k:"qcm",q:"Que mesure la variance d'une image ?",o:["La force de son contraste","La taille de ses motifs","Sa direction dominante"],why:"La variance mesure l'écart des pixels à la moyenne, sans tenir compte de leur position.",src:"cheng2021guide"},
  {k:"qcm",q:"Que manque-t-il à ces deux statistiques ?",o:["Une information sur les relations entre pixels voisins","Une meilleure précision numérique","La couleur"],why:"Tout ce qui fait une texture tient dans la façon dont les pixels dépendent les uns des autres.",src:"cheng2021guide"}]},
{id:"s3",t:"Le spectre de puissance",lvl:"Découverte",min:5,scene:["grf",9,{beta:2.2}],src:["cheng2021guide"],
 cards:[
  {h:"Décomposer en ondes",p:[`La transformée de Fourier écrit une image comme une somme d'ondes planes : des rayures régulières, de différentes longueurs d'onde et directions.`,`Chaque onde a une <b>amplitude</b>, sa force, et une <b>phase</b>, sa position. Le <b>spectre de puissance</b> ne garde que l'amplitude au carré : l'énergie contenue à chaque échelle.`]},
  {h:"Une pente qui change tout",p:[`Beaucoup de champs naturels ont un spectre en loi de puissance, P(k) ∝ k<sup>−β</sup>. Déplace le curseur : quand β augmente, l'énergie passe des petits détails aux grandes structures.`],sim:"spectrum"},
  {h:"L'outil standard",p:[`Le spectre est l'outil de base en physique : simple à calculer, facile à interpréter, parfait pour repérer une échelle caractéristique comme la longueur d'onde de la houle.`,`Mais il a jeté les phases. La leçon suivante montre ce que cela coûte.`]}],
 ex:[
  {k:"qcm",q:"Que conserve le spectre de puissance ?",o:["L'énergie à chaque échelle","La position de chaque structure","Les phases des ondes"],why:"Le spectre est le module au carré de la transformée de Fourier. Les phases sont perdues.",src:"cheng2021guide"},
  {k:"qcm",q:"Dans P(k) ∝ k^−β, on augmente β. L'image devient :",o:["plus lisse, dominée par les grandes structures","plus granuleuse","plus contrastée"],why:"Un β plus grand retire de l'énergie aux petites échelles, donc aux détails fins.",src:"cheng2021guide"},
  {k:"match",q:"Associe chaque grandeur de Fourier à ce qu'elle dit.",pairs:[["Amplitude","La force d'une onde"],["Phase","La position de l'onde"],["Nombre d'onde k","L'inverse de l'échelle"]],why:"Un grand k correspond à de petits détails, un petit k à de grandes structures.",src:"cheng2021guide"}]},
{id:"s4",t:"Ce que le spectre ne voit pas",lvl:"Découverte",min:5,scene:["cells",3,{}],src:["cheng2021guide","mallat2012"],
 cards:[
  {h:"Une expérience",p:[`Prends une image faite de taches aux bords nets. Garde l'amplitude de chaque onde de Fourier, mais brouille leurs phases. Le spectre de puissance ne change pas d'un iota.`,`Pousse le curseur à fond : les bords, les formes, tout a disparu. Il reste un brouillard qui a le même spectre.`],sim:"phases"},
  {h:"Gaussien et non gaussien",p:[`Un champ dont les phases sont tirées au hasard s'appelle un champ <b>gaussien</b>. Il est entièrement décrit par son spectre.`,`Les bords, les filaments, les cellules sont des structures <b>non gaussiennes</b>. Elles existent parce que les ondes de différentes échelles ont des phases accordées entre elles. On dit que les échelles sont <b>couplées</b>.`]},
  {h:"L'enjeu de la branche",p:[`Une cellule de pluie sur de la houle est exactement ce cas : une structure à bords nets posée sur un champ presque gaussien. Le spectre seul ne peut pas les distinguer proprement.`,`{{mallat2012}} montre que les coefficients de scattering dépendent de moments d'ordre élevé et séparent des processus de même spectre. Il nous faut d'abord un outil : l'ondelette.`]}],
 ex:[
  {k:"qcm",q:"On brouille les phases de Fourier d'une image. Que devient son spectre de puissance ?",o:["Il reste identique","Il s'aplatit","Il s'annule"],why:"Le spectre ne dépend que des amplitudes. Deux images très différentes peuvent donc avoir le même.",src:"cheng2021guide"},
  {k:"qcm",q:"Un champ gaussien est entièrement décrit par :",o:["son spectre de puissance","sa moyenne seule","ses phases"],why:"Ses phases étant aléatoires, toute l'information est dans les amplitudes.",src:"cheng2021guide"},
  {k:"qcm",q:"D'où viennent les bords nets et les filaments d'une image ?",o:["De phases accordées entre échelles","D'un spectre plus pentu","D'une variance plus forte"],why:"Un bord net exige que toutes les ondes, des grandes aux petites, s'alignent au même endroit.",src:"mallat2012"}]},
{id:"s5",t:"Une ondelette, c'est quoi ?",lvl:"Découverte",min:5,scene:["waves",3,{mw:.6,a:.8,lw:.16}],src:["mallat2012","cheng2021guide"],
 cards:[
  {h:"Une onde qui ne dure pas",p:[`Une onde de Fourier s'étend sur toute l'image : elle sait très bien « quelle échelle », pas du tout « où ».`,`Une <b>ondelette</b> est une petite onde enfermée dans une enveloppe : quelques oscillations, puis plus rien. Elle répond à la fois « quelle échelle » et « où ».`]},
  {h:"Une famille, pas une seule",p:[`On part d'une ondelette mère, puis on la dilate et on la tourne. Chaque membre de la famille est repéré par deux indices : l'échelle <b>j</b> et l'orientation <b>θ</b>.`,`Les échelles sont <b>dyadiques</b> : la taille double à chaque cran, 2<sup>j</sup> pixels. Change j et θ ci-dessous.`],sim:"wavelet"},
  {h:"J et L",p:[`<b>J</b> est le nombre d'échelles et <b>L</b> le nombre d'orientations. Avec J = 6 et L = 4, la famille compte 24 ondelettes et couvre des détails de quelques pixels jusqu'à des structures de plusieurs dizaines de pixels.`,`Dans l'espace de Fourier, chaque ondelette est une tache : elle sélectionne une bande d'échelles et un secteur de directions. {{mallat2012}} explique pourquoi ce regroupement en paquets dyadiques rend la description stable quand l'image se déforme.`]}],
 ex:[
  {k:"qcm",q:"Qu'apporte une ondelette par rapport à une onde de Fourier ?",o:["Elle est localisée : elle dit aussi où","Elle est plus rapide à calculer","Elle n'a pas de direction"],why:"L'enveloppe limite l'ondelette à une petite région de l'image.",src:"cheng2021guide"},
  {k:"qcm",q:"Avec J = 5 échelles et L = 4 orientations, combien d'ondelettes ?",o:["20","9","625"],why:"Une ondelette par couple (échelle, orientation) : 5 × 4 = 20.",src:"cheng2021guide"},
  {k:"qcm",q:"« Échelles dyadiques » signifie que d'un cran au suivant, la taille de l'ondelette :",o:["double","augmente d'un pixel","est multipliée par dix"],why:"L'échelle j correspond à 2^j pixels : 1, 2, 4, 8, 16…",src:"mallat2012"}]},
{id:"s6",t:"Passer l'image au peigne des ondelettes",lvl:"Découverte",min:5,scene:["rain",17,{d:.8,rw:0,g:.9}],src:["bruna2013","cheng2021guide"],
 cards:[
  {h:"Filtrer, c'est comparer partout",p:[`Filtrer une image par une ondelette, c'est poser l'ondelette à chaque position et mesurer à quel point l'image lui ressemble à cet endroit. On note cette opération I ⋆ ψ, une <b>convolution</b>.`,`Le résultat est une nouvelle image, de la même taille : une carte qui s'allume là où l'image contient des détails de cette échelle et de cette orientation.`]},
  {h:"Essaie",p:[`L'image de gauche mêle une houle et une cellule aux bords nets. Choisis une échelle et une orientation. La houle ne répond qu'à une seule ondelette, celle qui a sa longueur d'onde et sa direction. Les bords de la cellule répondent à presque toutes.`],sim:"filter-re"},
  {h:"Une pile de cartes",p:[`En passant les J × L ondelettes, on obtient J × L cartes : la <b>transformée en ondelettes</b>. Aucune information n'est perdue, mais ce n'est pas encore un résumé : on a plus de nombres qu'au départ.`,`{{bruna2013}} en font la première couche d'un réseau convolutif dont les filtres ne sont pas appris.`]}],
 ex:[
  {k:"qcm",q:"Que produit le filtrage d'une image par une ondelette ?",o:["Une carte de la même taille","Un seul nombre","Une image deux fois plus grande"],why:"La convolution donne une réponse en chaque position.",src:"bruna2013"},
  {k:"qcm",q:"Une houle régulière répond fortement :",o:["à l'ondelette de sa longueur d'onde et de sa direction","à toutes les ondelettes","à aucune ondelette"],why:"Une onde presque pure occupe une petite région de l'espace de Fourier, donc une seule ondelette.",src:"cheng2021guide"},
  {k:"qcm",q:"Un bord net répond :",o:["à de nombreuses échelles à la fois","à une seule échelle","seulement à la plus grande échelle"],why:"Un bord contient toutes les échelles, alignées au même endroit. C'est la signature du couplage.",src:"cheng2021guide"}]},
{id:"s7",t:"Le module : garder l'enveloppe",lvl:"Découverte",min:5,scene:["rain",5,{d:.8,rw:0,g:.9}],src:["mallat2012","cheng2021guide"],
 cards:[
  {h:"Un problème de moyenne",p:[`On veut résumer chaque carte par un nombre, en faisant sa moyenne. Mais une carte d'ondelettes oscille : autant de positif que de négatif. Sa moyenne vaut zéro, quelle que soit l'image.`]},
  {h:"La solution : le module",p:[`Les ondelettes utilisées sont <b>complexes</b> : chaque coefficient a un module et une phase. Le module |I ⋆ ψ| efface l'oscillation et garde l'<b>enveloppe</b> : la carte de l'endroit où se trouve l'énergie de cette échelle.`,`Passe de la partie réelle au module ci-dessous, et compare.`],sim:"filter-mod"},
  {h:"Pourquoi c'est la bonne non-linéarité",p:[`Le module est une opération non linéaire, et c'est voulu : aucune opération linéaire ne peut révéler un couplage entre échelles.`,`Dans la construction de {{mallat2012}}, le module retire la phase complexe à chaque étape de la cascade, et c'est lui qui rend le résultat invariant par translation sans le rendre instable.`]}],
 ex:[
  {k:"qcm",q:"Pourquoi ne peut-on pas simplement moyenner une carte d'ondelettes ?",o:["Elle oscille autour de zéro : la moyenne est nulle","Elle est trop grande","Elle contient du bruit"],why:"Une ondelette a une moyenne nulle, donc la carte filtrée aussi.",src:"cheng2021guide"},
  {k:"qcm",q:"Que montre la carte du module |I ⋆ ψ| ?",o:["Où se trouve l'énergie de cette échelle","La phase de chaque onde","L'image d'origine, floutée"],why:"Le module est l'enveloppe des oscillations.",src:"cheng2021guide"},
  {k:"qcm",q:"Pourquoi faut-il une opération non linéaire ?",o:["Pour accéder aux couplages entre échelles","Pour accélérer le calcul","Pour supprimer le bruit"],why:"Une opération linéaire traite chaque onde séparément. Elle ne peut pas dire si deux échelles sont liées.",src:"mallat2012"}]},
{id:"s8",t:"S1 et S2 : deux nombres par ondelette",lvl:"Découverte",min:6,scene:["cells",8,{}],src:["cheng2021guide","cheng2024"],
 cards:[
  {h:"Enfin des résumés",p:[`Pour chaque ondelette, on moyenne sur toute l'image.`,`<b>S1 = ⟨|I ⋆ ψ|⟩</b> : la moyenne du module.<br><b>S2 = ⟨|I ⋆ ψ|²⟩</b> : la moyenne du module au carré.`,`Avec J échelles et L orientations, cela fait 2 × J × L nombres. Les crochets ⟨ ⟩ signifient « moyenne sur tous les pixels ».`]},
  {h:"S2 est un spectre, S1 est autre chose",p:[`S2 mesure l'énergie dans la bande de l'ondelette : c'est le spectre de puissance, regroupé par paquets d'échelles. {{cheng2021guide}} font le même rapprochement.`,`S1 contient une information nouvelle. Le rapport <b>S1² / S2</b> mesure la <b>parcimonie</b> : si l'énergie est étalée partout, il est proche de π/4 ≈ 0,79. Si elle est concentrée en quelques endroits, comme sur des bords, il est nettement plus petit.`],sim:"filter-mod"},
  {h:"Ce qu'il manque encore",p:[`S1 et S2 décrivent chaque échelle séparément. Ils ne disent pas si les bords vus à l'échelle 2 sont au même endroit que ceux vus à l'échelle 4.`,`Pour cela il faut regarder deux échelles à la fois. C'est l'objet du scattering, puis des covariances S3 et S4 de {{cheng2024}}.`]}],
 ex:[
  {k:"match",q:"Associe chaque coefficient à ce qu'il mesure.",pairs:[["S2","L'énergie dans une bande d'échelles"],["S1","La moyenne de l'enveloppe"],["S1² / S2","La parcimonie : étalé ou concentré"]],why:"S2 est un spectre regroupé par bandes, S1 ajoute une information non gaussienne, et leur rapport la rend lisible.",src:"cheng2021guide"},
  {k:"qcm",q:"S1² / S2 vaut 0,3 pour une ondelette. Qu'en déduis-tu ?",o:["L'énergie de cette échelle est concentrée en quelques endroits","Le champ est gaussien à cette échelle","Il n'y a pas d'énergie à cette échelle"],why:"Un champ gaussien donne environ 0,79. Une valeur bien plus basse signale une structure localisée.",src:"cheng2021guide"},
  {k:"qcm",q:"Avec J = 6 et L = 4, combien de coefficients S1 et S2 au total ?",o:["48","24","10"],why:"24 ondelettes, deux coefficients chacune.",src:"cheng2024"}]},
{id:"s9",t:"La transformée de scattering",lvl:"Intermédiaire",min:6,scene:["streaks",7,{}],src:["mallat2012","bruna2013"],
 cards:[
  {h:"Recommencer sur l'enveloppe",p:[`La carte |I ⋆ ψ<sub>1</sub>| est une image comme une autre. On peut donc la filtrer à son tour par une seconde ondelette, plus grande, et reprendre le module : <b>| |I ⋆ ψ<sub>1</sub>| ⋆ ψ<sub>2</sub> |</b>.`,`Ce coefficient d'ordre 2 répond à la question : comment l'énergie de la petite échelle 1 est-elle répartie à la grande échelle 2 ? C'est une mesure directe du couplage.`]},
  {h:"Une cascade",p:[`Ondelette, module, ondelette, module, puis moyenne. {{mallat2012}} définit ainsi la <b>transformée de scattering</b> et démontre deux propriétés : elle ne change pas quand l'image est translatée, et elle varie peu quand l'image est légèrement déformée.`]},
  {h:"Un réseau sans apprentissage",p:[`La structure ressemble à un réseau de neurones convolutif : des filtres, une non-linéarité, une moyenne. {{bruna2013}} le présentent ainsi et montrent qu'il distingue des textures de même spectre de Fourier.`,`La différence est essentielle pour un physicien : les filtres sont des ondelettes fixées à l'avance. Il n'y a rien à entraîner, et chaque coefficient a un sens.`]}],
 ex:[
  {k:"order",q:"Remets les opérations du scattering d'ordre 2 dans l'ordre.",items:["Filtrer l'image par une petite ondelette","Prendre le module","Filtrer cette enveloppe par une ondelette plus grande","Prendre le module","Moyenner sur l'image"],why:"La cascade alterne ondelette et module, et se termine par une moyenne qui donne l'invariance par translation.",src:"mallat2012"},
  {k:"qcm",q:"Que mesure un coefficient de scattering d'ordre 2 ?",o:["Comment l'énergie d'une petite échelle se répartit à une plus grande échelle","L'énergie totale de l'image","La phase de Fourier"],why:"C'est une mesure de couplage entre deux échelles, inaccessible au spectre.",src:"bruna2013"},
  {k:"qcm",q:"En quoi le scattering diffère-t-il d'un réseau convolutif classique ?",o:["Ses filtres sont fixés, rien n'est appris","Il n'a pas de non-linéarité","Il ne fonctionne que sur des images carrées"],why:"Les ondelettes sont choisies à l'avance, ce qui rend les coefficients interprétables et évite tout entraînement.",src:"bruna2013"}]},
{id:"s10",t:"Du traitement d'image à la physique",lvl:"Intermédiaire",min:5,scene:["grf",21,{beta:2.6}],src:["portilla2000","allys2019","allys2020"],
 cards:[
  {h:"Une idée ancienne",p:[`Coupler les échelles pour décrire une texture n'est pas né avec le scattering. {{portilla2000}} décrivaient déjà une texture par des statistiques sur des paires de coefficients d'ondelettes voisins en position, orientation et échelle, et vérifiaient leur modèle en synthétisant de nouvelles textures.`]},
  {h:"L'arrivée en astrophysique",p:[`{{allys2019}} appliquent le scattering au milieu interstellaire, un milieu turbulent rempli de filaments. Ils observent que les coefficients varient régulièrement avec l'angle, et les résument par un ajustement : c'est la RWST, moins de 100 coefficients pour des cartes de 256 par 256.`]},
  {h:"Une autre famille : les WPH",p:[`{{allys2020}} introduisent les statistiques WPH. Au lieu du module, elles comparent directement les phases de deux échelles, après les avoir accordées. Sur des simulations cosmologiques, elles font mieux que spectre et bispectre réunis pour quatre paramètres sur cinq, et servent aussi à générer de nouveaux champs.`,`Scattering, WPH et covariances de scattering sont trois variantes d'un même cadre : des ondelettes, une non-linéarité, des moyennes.`]}],
 ex:[
  {k:"order",q:"Classe ces travaux du plus ancien au plus récent.",items:["Portilla et Simoncelli : statistiques jointes d'ondelettes","Mallat : transformée de scattering","Allys et al. : la RWST pour le milieu interstellaire","Allys et al. : les statistiques WPH"],why:"2000, 2012, 2019, 2020.",src:"allys2020"},
  {k:"qcm",q:"Sur quoi repose la réduction RWST ?",o:["La régularité des coefficients en fonction de l'angle","Un réseau de neurones entraîné","La suppression des grandes échelles"],why:"Les coefficients dépendent de l'angle de façon simple, ce qui permet de les remplacer par quelques paramètres d'ajustement.",src:"allys2019"},
  {k:"qcm",q:"Comment les WPH couplent-elles deux échelles ?",o:["En comparant leurs phases après les avoir accordées","En prenant le module puis en refiltrant","En comparant leurs spectres"],why:"C'est l'« harmonique de phase » : on multiplie la phase de la grande échelle pour qu'elle oscille au rythme de la petite.",src:"allys2020"}]},
{id:"s11",t:"Les covariances de scattering : S3 et S4",lvl:"Intermédiaire",min:7,scene:["cells",15,{}],src:["morel2022","cheng2024"],
 cards:[
  {h:"Corréler au lieu de cascader",p:[`{{morel2022}}, pour les séries temporelles, puis {{cheng2024}}, pour les images, proposent une variante : au lieu d'empiler les modules, on calcule des <b>covariances</b> entre cartes. Une covariance mesure si deux cartes varient ensemble.`,`Ces statistiques s'appellent <b>covariances de scattering</b> ou <b>spectres de scattering</b> : les deux noms désignent la même chose.`]},
  {h:"Quatre familles",p:[`<b>S1</b> et <b>S2</b> : tu les connais.`,`<b>S3 = Cov( I ⋆ ψ<sub>2</sub> , |I ⋆ ψ<sub>1</sub>| ⋆ ψ<sub>2</sub> )</b>. On compare l'image vue à la grande échelle 2 avec l'enveloppe de la petite échelle 1, vue elle aussi à l'échelle 2. S3 est sensible au signe et à la phase : il voit les asymétries.`,`<b>S4 = Cov( |I ⋆ ψ<sub>1</sub>| ⋆ ψ<sub>3</sub> , |I ⋆ ψ<sub>2</sub>| ⋆ ψ<sub>3</sub> )</b>. On compare les enveloppes de deux échelles, toutes deux vues à une troisième échelle plus grande. S4 dit si l'énergie de deux échelles est concentrée aux mêmes endroits.`]},
  {h:"Ce que cela apporte",p:[`Pour un champ gaussien, S3 et S4 sont nuls une fois normalisés. Tout écart signale une structure. Ces statistiques captent des moments jusqu'à l'ordre quatre et s'estiment sur une seule image.`,`{{cheng2024}} réduisent ensuite leur nombre en exploitant les symétries du champ et la régularité des coefficients en échelle et en angle.`]}],
 ex:[
  {k:"match",q:"Associe chaque coefficient à ce qu'il compare.",pairs:[["S2","Une carte d'ondelettes avec elle-même"],["S3","L'image à grande échelle et l'enveloppe d'une petite échelle"],["S4","Les enveloppes de deux échelles"]],why:"S2 est une énergie, S3 un couplage signé entre signal et enveloppe, S4 un couplage entre enveloppes.",src:"cheng2024"},
  {k:"qcm",q:"Pour un champ gaussien, que valent S3 et S4 normalisés ?",o:["Zéro","Un","Ils sont égaux à S2"],why:"Un champ gaussien n'a aucun couplage entre échelles : ses phases sont indépendantes.",src:"cheng2024"},
  {k:"qcm",q:"« Covariance de scattering » et « spectre de scattering » désignent :",o:["la même famille de statistiques","deux méthodes concurrentes","l'une le cas 1D, l'autre le spectre de Fourier"],why:"Le nom a changé entre la première version de l'article de Morel et al. et les suivantes.",src:"morel2022"},
  {k:"qcm",q:"Sur combien d'images faut-il estimer ces statistiques ?",o:["Une seule peut suffire","Au moins mille","Autant que de coefficients"],why:"C'est l'un des arguments de Cheng et al. : la description est assez compacte pour être estimée sur un échantillon.",src:"cheng2024"}]},
{id:"s12",t:"Générer un champ à partir de ses statistiques",lvl:"Intermédiaire",min:6,scene:["grf",33,{beta:1.8}],src:["bruna2019","allys2020","cheng2024","mousset2024"],
 cards:[
  {h:"Le test ultime d'un résumé",p:[`Comment savoir si des statistiques décrivent vraiment une texture ? En fabriquant une nouvelle image qui a ces statistiques, et en regardant si elle ressemble à l'originale.`,`Si oui, les statistiques ont capté l'essentiel. Si l'image synthétique ressemble à un brouillard, il manque quelque chose : c'est ce qui arrive avec le spectre seul, comme dans la leçon 4.`]},
  {h:"La recette",p:[`{{bruna2019}} la formalisent sous le nom de modèle <b>microcanonique</b> : on mesure les statistiques Φ(x) sur un exemple x, on part d'un bruit blanc u, et on modifie u pixel par pixel pour réduire l'écart ‖Φ(u) − Φ(x)‖².`,`La modification suit une <b>descente de gradient</b> : à chaque pas, on calcule dans quelle direction changer chaque pixel pour diminuer l'écart. En pratique on utilise souvent l'algorithme L-BFGS, une descente de gradient améliorée.`]},
  {h:"Un modèle génératif",p:[`Chaque bruit de départ donne une image différente, avec les mêmes statistiques : on a un générateur de nouvelles réalisations, construit à partir d'un seul exemple.`,`{{allys2020}} l'ont fait avec les WPH, {{cheng2024}} avec les spectres de scattering, {{mousset2024}} sur la sphère. Et la même mécanique d'optimisation va servir à séparer des composantes.`]}],
 ex:[
  {k:"order",q:"Remets les étapes de la synthèse dans l'ordre.",items:["Mesurer les statistiques sur l'exemple","Partir d'un bruit blanc","Calculer l'écart entre les statistiques du bruit et celles de l'exemple","Modifier les pixels par descente de gradient","Répéter jusqu'à ce que l'écart soit petit"],why:"On ne copie jamais l'exemple : on ne lui emprunte que ses statistiques.",src:"bruna2019"},
  {k:"qcm",q:"Que modifie la descente de gradient pendant la synthèse ?",o:["Les pixels de l'image en cours","Les ondelettes","Les statistiques de l'exemple"],why:"Les ondelettes et la cible sont fixes. Seule l'image candidate évolue.",src:"bruna2019"},
  {k:"qcm",q:"Pourquoi générer des images est-il un bon test des statistiques ?",o:["Si la synthèse ressemble à l'original, les statistiques ont capté l'essentiel","Parce que c'est plus rapide que de les calculer","Parce que cela supprime le bruit"],why:"C'est l'argument de Portilla et Simoncelli, repris par toute la littérature du scattering.",src:"cheng2024"}]},
{id:"s13",t:"Séparer deux composantes : le problème",lvl:"Avancé",min:6,scene:["rain",29,{d:.6,rw:.3,g:.7}],src:["regaldo2021"],
 cards:[
  {h:"Une somme, deux inconnues",p:[`On observe une image d qui est la somme de deux choses : <b>d = s + n</b>. Le signal s nous intéresse. L'autre composante n, appelée bruit ou contamination, nous gêne. On voudrait retrouver s.`,`Pixel par pixel, c'est impossible : une équation, deux inconnues. Le problème est <b>mal posé</b>. Il faut une information supplémentaire.`],sim:"mix"},
  {h:"Les solutions classiques et leurs limites",p:[`Un filtre linéaire coupe les échelles où le bruit domine. Il fonctionne quand signal et bruit occupent des échelles différentes, et il détruit le signal là où ils se recouvrent.`,`Quand les deux composantes partagent les mêmes échelles mais pas la même <b>structure</b>, il faut des statistiques qui voient la structure.`]},
  {h:"L'information supplémentaire",p:[`{{regaldo2021}} partent d'une hypothèse raisonnable dans leur cas : on ne connaît pas la réalisation du bruit présente dans d, mais on sait en fabriquer autant d'autres qu'on veut, notées n<sub>1</sub>, n<sub>2</sub>, …`,`Autrement dit, on connaît le <b>processus</b> du bruit sans connaître son <b>tirage</b>. C'est la leçon 1 qui revient, et c'est ce qui rend le problème soluble.`]}],
 ex:[
  {k:"qcm",q:"Pourquoi d = s + n ne se résout-il pas pixel par pixel ?",o:["Une équation pour deux inconnues","Le bruit est trop fort","Les pixels sont trop nombreux"],why:"Sans information supplémentaire, toute répartition entre s et n est acceptable.",src:"regaldo2021"},
  {k:"qcm",q:"Quelle information le débruitage statistique suppose-t-il disponible ?",o:["Des réalisations du bruit, à volonté","La vraie carte du signal","La réalisation exacte du bruit présent dans les données"],why:"On connaît le processus du bruit, par des simulations ou des mesures, mais pas son tirage dans d.",src:"regaldo2021"},
  {k:"qcm",q:"Quand un filtre linéaire échoue-t-il ?",o:["Quand signal et bruit occupent les mêmes échelles","Quand l'image est trop grande","Quand le bruit est gaussien"],why:"Un filtre linéaire trie par échelle. Il ne peut pas séparer deux composantes de même spectre.",src:"regaldo2021"}]},
{id:"s14",t:"Le débruitage statistique",lvl:"Avancé",min:7,scene:["cells",22,{}],src:["regaldo2021","delouis2022"],
 cards:[
  {h:"L'idée en une phrase",p:[`On cherche une carte u telle que, si on lui ajoute du bruit, on obtient quelque chose qui a les mêmes statistiques que les données.`,`En formule : on minimise <b>‖Φ(u + n<sub>i</sub>) − Φ(d)‖²</b>, en moyenne sur les réalisations n<sub>i</sub>. Φ désigne les statistiques, WPH chez {{regaldo2021}}. L'optimisation se fait sur les pixels de u, comme une synthèse, en partant de u = d.`]},
  {h:"Ce que la méthode retrouve",p:[`Sur une simulation où la vérité est connue, la carte obtenue reproduit le vrai spectre jusqu'à des échelles où le bruit est dix fois plus puissant que le signal, et retrouve une partie des propriétés non gaussiennes.`,`{{delouis2022}} étendent la méthode au ciel entier, sur la sphère, avec des coefficients de scattering et des statistiques <b>croisées</b> entre cartes : deux moitiés de mission dont les bruits sont indépendants, et la température avec la polarisation.`]},
  {h:"La réserve à retenir",p:[`{{delouis2022}} le disent nettement : aux échelles où le signal est dix fois plus faible que le bruit, les structures de la carte produite ont les bonnes statistiques mais ne sont plus au bon endroit.`,`La méthode rend une carte <b>statistiquement</b> juste. Elle ne garantit pas que chaque détail soit vrai. C'est une distinction à garder en tête pour toute application.`]}],
 ex:[
  {k:"qcm",q:"Que compare la perte du débruitage statistique ?",o:["Les statistiques de u + bruit avec celles des données","Les pixels de u avec ceux des données","Le spectre de u avec celui du bruit"],why:"On ne demande pas à u de ressembler à d, mais à u bruité d'être statistiquement indiscernable de d.",src:"regaldo2021"},
  {k:"qcm",q:"Aux échelles où le bruit domine largement, que peut-on dire de la carte produite ?",o:["Ses structures ont les bonnes statistiques, mais pas forcément la bonne position","Elle est exacte pixel par pixel","Elle est vide"],why:"C'est la limite énoncée par Delouis et al. : la méthode est statistique.",src:"delouis2022"},
  {k:"qcm",q:"À quoi servent les statistiques croisées entre deux moitiés de mission ?",o:["À exploiter le fait que leurs bruits sont indépendants","À doubler la résolution","À supprimer les grandes échelles"],why:"Le signal est commun aux deux cartes, pas le bruit : leur corrélation isole le signal.",src:"delouis2022"},
  {k:"order",q:"Remets l'algorithme dans l'ordre.",items:["Calculer les statistiques des données d","Initialiser u avec d","Ajouter des réalisations de bruit à u et calculer les statistiques","Mesurer l'écart avec les statistiques de d","Corriger les pixels de u par descente de gradient"],why:"C'est une synthèse sous contrainte : la cible est d, et le bruit est ajouté à chaque évaluation.",src:"regaldo2021"}]},
{id:"s15",t:"Quand les deux composantes ont une structure",lvl:"Avancé",min:6,scene:["lowwind",9,{}],src:["auclair2024","siahkoohi2023"],
 cards:[
  {h:"Plus de « bruit » au sens habituel",p:[`Jusqu'ici la composante gênante était un bruit instrumental. {{auclair2024}} traitent un cas plus dur : séparer la poussière de notre Galaxie du fond infrarouge cosmologique, la lumière cumulée de galaxies lointaines. Les deux sont des signaux astrophysiques, tous deux non gaussiens, observés à une seule longueur d'onde.`]},
  {h:"Apprendre l'autre composante ailleurs",p:[`Leur solution : observer une région du ciel presque dépourvue de poussière, et y mesurer les statistiques du fond seul. Cette région joue le rôle des « réalisations de bruit » des leçons précédentes.`,`La séparation repose alors uniquement sur la différence de structure spatiale entre les deux composantes.`]},
  {h:"Et si on ne sait pas quelles sources sont là ?",p:[`{{siahkoohi2023}} vont un cran plus loin sur les données sismiques de la mission InSight. Ils commencent par regrouper automatiquement les morceaux de signal dans l'espace des spectres de scattering, avec un autoencodeur variationnel. Chaque groupe fournit ensuite les exemples qui servent d'a priori à la séparation.`,`Le schéma général est le même partout : un exemple de ce qu'on veut retirer, des statistiques qui voient la structure, une optimisation sur les pixels.`]}],
 ex:[
  {k:"qcm",q:"Qu'est-ce qui rend le cas d'Auclair et al. plus difficile que le débruitage ?",o:["Les deux composantes sont non gaussiennes","Les images sont plus grandes","Il n'y a pas d'ondelettes adaptées"],why:"Un bruit instrumental est souvent proche d'un champ gaussien. Ici, les deux composantes ont de la structure.",src:"auclair2024"},
  {k:"qcm",q:"D'où viennent les statistiques du fond infrarouge dans leur méthode ?",o:["D'une autre région du ciel, presque sans poussière","D'une simulation numérique seule","D'une autre longueur d'onde"],why:"Une observation indépendante fournit des exemples de la composante à retirer.",src:"auclair2024"},
  {k:"qcm",q:"Que fait l'étape de regroupement chez Siahkoohi et al. ?",o:["Elle identifie les types de sources présents, sans étiquettes","Elle supprime le bruit blanc","Elle calcule le spectre de puissance"],why:"Le regroupement non supervisé fournit les exemples de chaque source, qui servent ensuite d'a priori.",src:"siahkoohi2023"}]},
{id:"s16",t:"Tsouros et al. : sept contraintes à la fois",lvl:"Avancé",min:8,scene:["front",12,{}],src:["tsouros2026","cheng2024","delouis2022"],
 cards:[
  {h:"Le cadre",p:[`{{tsouros2026}} cherchent de meilleures cartes de la poussière polarisée à partir des données Planck à 353 GHz. Pour chaque paramètre de Stokes Q et U, le modèle est <b>d = s + c</b>, où la contamination c réunit le bruit instrumental et des résidus du fond cosmologique. Ils disposent de 100 réalisations de c.`,`Les statistiques sont des covariances de scattering : <b>Φ(x) = { μ/σ, log S1, log S2, S3, S4 }</b>, avec 7 échelles et 4 orientations. Le logarithme appliqué à S1 et S2 équilibre le poids des petites et des grandes échelles et aide la convergence.`]},
  {h:"Les sept pertes",p:[`<b>Cohérence avec les données</b> (une pour Q, une pour U) : les statistiques de u + c doivent égaler celles de d. C'est la perte de la leçon 14.`,`<b>Cohérence du résidu</b> (Q et U) : d − u, ce qu'on a retiré, doit avoir les statistiques moyennes de la contamination.`,`<b>Croisée Q–U</b> : les statistiques croisées de (u<sub>Q</sub> + c<sub>Q</sub>, u<sub>U</sub> + c<sub>U</sub>) doivent égaler celles de (d<sub>Q</sub>, d<sub>U</sub>).`,`<b>Croisées avec l'intensité</b> (Q et U) : même chose avec une carte d'intensité à 857 GHz, dominée par la poussière, qui sert de traceur indépendant.`]},
  {h:"Résultats et limites",p:[`L'optimisation se fait par L-BFGS sur les pixels, avec un lot de 10 réalisations de contamination tiré à chaque itération. Sur une région test où la vérité est connue, le signal est retrouvé à travers les échelles, y compris là où la contamination dépasse la poussière d'un à deux ordres de grandeur.`,`Les auteurs signalent eux-mêmes les limites : pas d'incertitudes fournies, sensibilité à un modèle de contamination imparfait, et une carte moyennée plus fidèle pixel par pixel mais lissée.`]},
  {h:"Transposer à une vignette SAR",p:[`Ce paragraphe n'est pas tiré d'un article : c'est une lecture du cadre pour ton cas. Une vignette du mode vagues s'écrirait d = houle + signature atmosphérique. Trois questions se posent alors, les mêmes que dans chaque article de cette branche.`,`D'où viennent les exemples de la composante à retirer ? Quelles statistiques la distinguent de l'autre ? Et quelle perte empêche l'optimisation de mettre de la houle dans le résidu, ou l'inverse ? La perte sur le résidu de Tsouros et al. répond précisément à cette troisième question.`]}],
 ex:[
  {k:"match",q:"Associe chaque perte à ce qu'elle impose.",pairs:[["Cohérence avec les données","u + c a les statistiques de d"],["Cohérence du résidu","d − u a les statistiques de la contamination"],["Croisée avec l'intensité","u reste lié à un traceur indépendant de la poussière"]],why:"La première tire u vers les données, la deuxième vérifie ce qu'on a retiré, la troisième ajoute une information extérieure.",src:"tsouros2026"},
  {k:"qcm",q:"Pourquoi prendre le logarithme de S1 et S2 ?",o:["Pour équilibrer les échelles et aider la convergence","Pour rendre les coefficients positifs","Pour supprimer S3 et S4"],why:"S1 et S2 varient sur plusieurs ordres de grandeur entre petites et grandes échelles. Le logarithme les ramène à des valeurs comparables.",src:"tsouros2026"},
  {k:"qcm",q:"Quelle limite les auteurs reconnaissent-ils ?",o:["Aucune incertitude n'est fournie sur les cartes","La méthode ne fonctionne qu'à haut rapport signal sur bruit","Il faut des milliers de réalisations de contamination"],why:"L'estimation des incertitudes est renvoyée à un autre travail. La méthode fonctionne au contraire là où la contamination domine.",src:"tsouros2026"},
  {k:"qcm",q:"Que contrôle la perte sur le résidu d − u ?",o:["Que ce qu'on retire ressemble bien à de la contamination","Que u soit lisse","Que le spectre de u soit plat"],why:"Sans elle, l'optimisation pourrait laisser du signal dans le résidu tant que u + c reste compatible avec d.",src:"tsouros2026"}]}
],
paths:[
 {t:"Comprendre le scattering pas à pas",ids:["cheng2021guide","bruna2013","mallat2012","allys2019","allys2020","morel2022","cheng2024"]},
 {t:"Générer, puis séparer",ids:["portilla2000","bruna2019","regaldo2021","delouis2022","auclair2024","siahkoohi2023","tsouros2026"]}
],
synth:[
 {t:"Du spectre aux covariances de scattering",p:[
  `<b>Le constat.</b> Le spectre de puissance décrit entièrement un champ gaussien et rien d'autre : il ignore les phases, donc les bords et les filaments ({{cheng2021guide}}).`,
  `<b>La construction.</b> {{mallat2012}} enchaîne ondelettes et modules pour obtenir des coefficients invariants par translation, stables aux déformations et sensibles aux moments d'ordre élevé. {{bruna2013}} en font un réseau convolutif sans apprentissage.`,
  `<b>L'entrée en physique.</b> {{allys2019}} adaptent le scattering au milieu interstellaire, {{allys2020}} proposent les WPH, qui couplent les échelles par les phases.`,
  `<b>La forme actuelle.</b> {{morel2022}} puis {{cheng2024}} remplacent la cascade par des covariances entre cartes d'ondelettes et enveloppes : S1 à S4, estimables sur une seule image.`,
  `<b>Le critère de validation.</b> Depuis {{portilla2000}}, une description est jugée sur sa capacité à générer : {{bruna2019}} en donnent le cadre, {{mousset2024}} l'étendent à la sphère.`]},
 {t:"Séparer des composantes par leurs statistiques",p:[
  `<b>L'idée fondatrice.</b> {{regaldo2021}} optimisent une carte pour que ses statistiques, une fois le bruit ajouté, reproduisent celles des données. Il suffit de savoir simuler le bruit.`,
  `<b>Le passage à l'échelle.</b> {{delouis2022}} traitent le ciel entier et ajoutent des statistiques croisées entre cartes.`,
  `<b>Deux composantes structurées.</b> {{auclair2024}} séparent deux signaux non gaussiens à une seule fréquence, en apprenant l'un des deux sur une autre région. {{siahkoohi2023}} trouvent les sources par regroupement avant de les séparer.`,
  `<b>Plusieurs contraintes.</b> {{tsouros2026}} somment sept pertes, dont une sur le résidu et des croisées avec un traceur indépendant, sur des covariances de scattering en logarithme.`,
  `<b>Ce qui reste ouvert.</b> Les cartes produites sont justes statistiquement, pas pixel par pixel là où la contamination domine ({{delouis2022}}). Les incertitudes ne sont pas encore fournies ({{tsouros2026}}). Et tout dépend de la qualité des exemples de la composante à retirer.`]}
]
};
